# Skate3Recomp custom-music build script (generated by Claude for dekp23).
# Builds dekp23/skate3recomp-customplayer (branch custom-music-import) into C:\s3build
# and assembles C:\s3build\Skate3Recomp-CustomMusic. The existing install is only read.
# Progress: status.txt (current step) and build.log (full output) next to this script.

$ErrorActionPreference = 'Stop'
$Here      = Split-Path -Parent $MyInvocation.MyCommand.Path
$Install   = Split-Path -Parent $Here                         # ...\Skate3Recomp-Windows
$GameDir   = Join-Path $Install 'game'
$Root      = 'C:\s3build'
$Repo      = Join-Path $Root 'skate3recomp'
$OutDir    = Join-Path $Root 'Skate3Recomp-CustomMusic'
$MusicDir  = Join-Path $Root 'custom_music'
$RepoUrl   = 'https://github.com/dekp23/skate3recomp-customplayer.git'
$Branch    = 'custom-music-import'
$TuName    = 'TU_12K2276_000000C000000.00000000000O3'
$TuUrl     = 'https://xboxunity.net/Resources/Lib/TitleUpdate.php?tuid=21774'
$Preset    = 'release'
$Log       = Join-Path $Here 'build.log'
$Status    = Join-Path $Here 'status.txt'

function Log([string]$m) {
  $line = "$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')  $m"
  Write-Host $line -ForegroundColor Cyan
  Add-Content -Path $Log -Value $line -Encoding UTF8
}
function Step([string]$m) {
  Log "STEP $m"
  Set-Content -Path $Status -Value "STEP $m  (since $(Get-Date -Format 'HH:mm:ss'))" -Encoding UTF8
}
function Run([string]$exe, [string[]]$argv) {
  Log "> $exe $($argv -join ' ')"
  $old = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
  & $exe @argv 2>&1 | ForEach-Object {
    $l = if ($_ -is [System.Management.Automation.ErrorRecord]) { $_.Exception.Message } else { "$_" }
    Write-Host $l; Add-Content -Path $Log -Value $l -Encoding UTF8
  }
  $code = $LASTEXITCODE; $ErrorActionPreference = $old
  if ($code -ne 0) { throw "$exe exited with code $code" }
}
function Refresh-Path {
  $env:Path = [Environment]::GetEnvironmentVariable('Path', 'Machine') + ';' +
              [Environment]::GetEnvironmentVariable('Path', 'User')
  foreach ($p in @('C:\Program Files\LLVM\bin', 'C:\Program Files\CMake\bin', 'C:\Program Files\Git\cmd',
                   "$env:LOCALAPPDATA\Microsoft\WinGet\Links")) {
    if ((Test-Path $p) -and ($env:Path -notlike "*$p*")) { $env:Path = "$p;$env:Path" }
  }
}
function Has([string]$cmd) { [bool](Get-Command $cmd -ErrorAction SilentlyContinue) }
function Python-Works {
  foreach ($c in @('py', 'python')) {
    if (Has $c) {
      $old = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
      $v = & $c --version 2>&1; $ok = ($LASTEXITCODE -eq 0) -and ("$v" -match 'Python 3\.')
      $ErrorActionPreference = $old
      if ($ok) { return $true }
    }
  }
  return $false
}
function Winget-Install([string]$id, [string[]]$extra = @()) {
  Log "installing $id (approve the Windows UAC prompt if one appears)"
  $argv = @('install', '--id', $id, '-e', '--source', 'winget',
            '--accept-package-agreements', '--accept-source-agreements') + $extra
  $old = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
  & winget @argv 2>&1 | ForEach-Object { $l = "$_"; Write-Host $l; Add-Content -Path $Log -Value $l -Encoding UTF8 }
  $code = $LASTEXITCODE; $ErrorActionPreference = $old
  # -1978335189 = already installed / no upgrade available
  if ($code -ne 0 -and $code -ne -1978335189) { throw "winget install $id failed ($code)" }
}
function VS-Path {
  $vswhere = "${env:ProgramFiles(x86)}\Microsoft Visual Studio\Installer\vswhere.exe"
  if (-not (Test-Path $vswhere)) { return $null }
  $p = & $vswhere -latest -products * -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 `
         -property installationPath 2>$null
  if ($p) { return "$p".Trim() } else { return $null }
}

try {
  New-Item -ItemType Directory -Force -Path $Root | Out-Null
  Set-Content -Path $Log -Value "Skate3Recomp custom-music build log" -Encoding UTF8
  Log "install=$Install game=$GameDir root=$Root"

  # ---------------------------------------------------------------- checks
  Step '1/8 checking disk space and game files'
  $freeGB = [math]::Round((Get-PSDrive C).Free / 1GB, 1)
  Log "C: free space: $freeGB GB"
  if ($freeGB -lt 25) { throw "only $freeGB GB free on C:, need about 25 GB or more" }
  foreach ($f in @('default.xex', 'data\webkit\EAWebkit.xex')) {
    if (-not (Test-Path (Join-Path $GameDir $f))) { throw "missing $GameDir\$f" }
  }

  # ---------------------------------------------------------------- toolchain
  Step '2/8 installing missing build tools'
  if (-not (Has 'winget')) { throw 'winget not found (install "App Installer" from the Microsoft Store)' }
  Refresh-Path
  if (-not (Has 'git'))   { Winget-Install 'Git.Git' }
  if (-not (Has 'cmake')) { Winget-Install 'Kitware.CMake' }
  if (-not (Has 'ninja')) { Winget-Install 'Ninja-build.Ninja' }
  if (-not (Has 'clang')) { Winget-Install 'LLVM.LLVM' }
  if (-not (Python-Works)) { Winget-Install 'Python.Python.3.12' }
  if (-not (VS-Path)) {
    $vsArgs = '--passive --wait --norestart --add Microsoft.VisualStudio.Workload.VCTools --includeRecommended'
    Winget-Install 'Microsoft.VisualStudio.2022.BuildTools' @('--override', $vsArgs)
    if (-not (VS-Path)) {
      # Build Tools present without the C++ workload: add it.
      $setup = "${env:ProgramFiles(x86)}\Microsoft Visual Studio\Installer\setup.exe"
      $bt = "${env:ProgramFiles(x86)}\Microsoft Visual Studio\2022\BuildTools"
      if ((Test-Path $setup) -and (Test-Path $bt)) {
        Run $setup @('modify', '--installPath', $bt, '--add', 'Microsoft.VisualStudio.Workload.VCTools',
                     '--includeRecommended', '--passive', '--norestart', '--wait')
      }
    }
  }
  Refresh-Path
  $vs = VS-Path
  if (-not $vs) { throw 'Visual Studio C++ build tools still not found after install' }
  foreach ($t in @('git', 'cmake', 'ninja', 'clang')) { if (-not (Has $t)) { throw "$t still not on PATH after install" } }
  if (-not (Python-Works)) { throw 'Python 3 still not usable after install' }

  # MSVC environment (Windows SDK headers/libs, rc.exe), then LLVM first on PATH.
  $vcvars = Join-Path $vs 'VC\Auxiliary\Build\vcvars64.bat'
  cmd /s /c "`"`"$vcvars`" >nul 2>&1 && set`"" | ForEach-Object {
    if ($_ -match '^([^=]+)=(.*)$') { Set-Item -Path "env:$($matches[1])" -Value $matches[2] }
  }
  $env:Path = "C:\Program Files\LLVM\bin;$env:Path"
  $env:CC = 'clang'; $env:CXX = 'clang++'
  Run 'clang' @('--version')
  Run 'cmake' @('--version')
  $clangMajor = [int](((& clang --version) -join ' ') -replace '.*clang version (\d+).*', '$1')
  if ($clangMajor -lt 18) { throw "clang $clangMajor is too old (need 18+)" }

  # ---------------------------------------------------------------- source
  Step '3/8 downloading source (with submodules, can take a while)'
  if (-not (Test-Path (Join-Path $Repo '.git'))) {
    Run 'git' @('-c', 'core.longpaths=true', 'clone', '--branch', $Branch, $RepoUrl, $Repo)
  } else {
    Run 'git' @('-C', $Repo, 'fetch', 'origin', $Branch)
    Run 'git' @('-C', $Repo, 'checkout', $Branch)
    Run 'git' @('-C', $Repo, 'reset', '--hard', "origin/$Branch")
  }
  Run 'git' @('-C', $Repo, 'config', 'core.longpaths', 'true')
  Run 'git' @('-C', $Repo, 'submodule', 'sync', '--recursive')
  Run 'git' @('-C', $Repo, '-c', 'core.longpaths=true', 'submodule', 'update', '--init', '--recursive', '--jobs', '4')
  # Repair submodules left cloned-but-unchecked-out by an interrupted earlier run.
  Run 'git' @('-C', $Repo, 'submodule', 'foreach', '--recursive', '--quiet', 'git reset --hard -q')
  foreach ($f in @('third_party\rexglue-sdk\thirdparty\o1heap\o1heap\o1heap.c',
                   'third_party\rexglue-sdk\thirdparty\imgui\imgui.h',
                   'third_party\rexglue-sdk\thirdparty\FFmpeg\libavcodec\avcodec.h')) {
    if (-not (Test-Path (Join-Path $Repo $f))) { throw "submodule file missing after checkout: $f" }
  }
  Run 'git' @('-C', $Repo, 'log', '-1', '--oneline')
  Run 'git' @('-C', $Repo, 'submodule', 'status', 'third_party/rexglue-sdk')

  # ---------------------------------------------------------------- title update
  Step '4/8 downloading Title Update 3 package'
  $tu = Join-Path $Repo $TuName
  if (-not (Test-Path $tu)) {
    $ProgressPreference = 'SilentlyContinue'
    Invoke-WebRequest -Uri $TuUrl -OutFile $tu -UseBasicParsing
  }
  $bytes = [System.IO.File]::ReadAllBytes($tu)
  $magic = [System.Text.Encoding]::ASCII.GetString($bytes, 0, 4)
  Log "TU package: $($bytes.Length) bytes, magic '$magic'"
  if ($magic -notin @('LIVE', 'PIRS', 'CON ')) {
    Remove-Item $tu
    throw "downloaded TU is not an Xbox package (magic '$magic'); the download URL may have changed"
  }

  # ---------------------------------------------------------------- build
  $mem = [math]::Floor((Get-CimInstance Win32_ComputerSystem).TotalPhysicalMemory / 1GB)
  $cores = [Environment]::ProcessorCount
  $jobs = [math]::Max(1, [math]::Min($cores, [math]::Floor($mem / 2.5)))
  Log "RAM $mem GB, $cores logical cores -> $jobs parallel jobs"
  $gameCMake = $GameDir -replace '\\', '/'
  Push-Location $Repo
  try {
    Step '5/8 configuring'
    Run 'cmake' @('--preset', $Preset, "-DSKATE3_GAME_DATA_ROOT=$gameCMake")
    Step '6/8 generating recompiled source (codegen)'
    Run 'cmake' @('--build', '--preset', $Preset, '--target', 'generate-all', '--parallel', "$jobs")
    Step '7/8 compiling (longest step)'
    Run 'cmake' @('--preset', $Preset, "-DSKATE3_GAME_DATA_ROOT=$gameCMake")
    Run 'cmake' @('--build', '--preset', $Preset, '--parallel', "$jobs")
  } finally { Pop-Location }

  # ---------------------------------------------------------------- package
  Step '8/8 assembling Skate3Recomp-CustomMusic'
  $buildDir = Join-Path $Repo "out\build\$Preset"
  $exe = Get-ChildItem -Path $buildDir -Filter 'skate3.exe' -Recurse | Select-Object -First 1
  if (-not $exe) { throw "skate3.exe not found under $buildDir" }
  New-Item -ItemType Directory -Force -Path $OutDir, $MusicDir | Out-Null
  Copy-Item $exe.FullName $OutDir -Force
  Get-ChildItem -Path $exe.DirectoryName -Filter '*.dll' | Copy-Item -Destination $OutDir -Force
  Copy-Item (Join-Path $Install 'portable.txt') $OutDir -Force
  $gameLink = Join-Path $OutDir 'game'
  if (-not (Test-Path $gameLink)) { New-Item -ItemType Junction -Path $gameLink -Target $GameDir | Out-Null }
  $dlcSrc = Join-Path $Install 'dlc'
  $dlcLink = Join-Path $OutDir 'dlc'
  if ((Test-Path $dlcSrc) -and -not (Test-Path $dlcLink)) {
    New-Item -ItemType Junction -Path $dlcLink -Target $dlcSrc | Out-Null
  }
  $savesSrc = Join-Path $Install 'saves'
  if ((Test-Path $savesSrc) -and -not (Test-Path (Join-Path $OutDir 'saves'))) {
    Copy-Item $savesSrc $OutDir -Recurse   # copy, not link: originals stay untouched
  }
  # Settings: copy yours once (v2 also repairs the copy the v1 script corrupted).
  # The music folder is NOT configured here: the runtime finds custom_music next to the exe.
  $settings = Join-Path $OutDir 'settings.toml'
  $marker = Join-Path $OutDir '.settings_copied_v2'
  if (-not (Test-Path $marker)) {
    Copy-Item (Join-Path $Install 'settings.toml') $settings -Force
    Set-Content -Path $marker -Value 'settings.toml copied from the original install' -Encoding ASCII
  }
  $musicLink = Join-Path $OutDir 'custom_music'
  if (-not (Test-Path $musicLink)) { New-Item -ItemType Junction -Path $musicLink -Target $MusicDir | Out-Null }
  Get-ChildItem $OutDir | ForEach-Object { Log "  $($_.Name)" }

  Log "RESULT: SUCCESS -> $OutDir"
  Set-Content -Path $Status -Value "RESULT: SUCCESS $(Get-Date -Format 'HH:mm:ss') -> $OutDir" -Encoding UTF8
  Write-Host "`nBuild finished. New game folder: $OutDir" -ForegroundColor Green
}
catch {
  $msg = $_.Exception.Message
  Log "RESULT: FAILED - $msg"
  Set-Content -Path $Status -Value "RESULT: FAILED $(Get-Date -Format 'HH:mm:ss') - $msg" -Encoding UTF8
  Write-Host "`nBuild FAILED: $msg  (see $Log)" -ForegroundColor Red
  exit 1
}
